import { timingSafeEqual } from 'node:crypto'
import { singleton } from 'tsyringe-neo'
import { BaseError } from '@bk-dash/core-typescript'
import type { HttpControllerRequest, HttpMiddlewareResponse, Middleware } from '@bk-dash/core-typescript'
import type { InterfaceErrors } from '../errors'

/**
 * Guards internal/admin billing operations with a shared secret. Compares the
 * `x-internal-secret` request header against env `BILLING_INTERNAL_SECRET`.
 * No session — this is a back-office key, not a user role.
 */
@singleton()
export class InternalSecretKeyMiddleware implements Middleware {
	async execute(request: HttpControllerRequest<unknown>): Promise<HttpMiddlewareResponse<void>> {
		const expected = process.env.BILLING_INTERNAL_SECRET
		const provided = request.raw.headers.get('x-internal-secret')
		if (!expected || !provided || !this.secretsMatch(provided, expected)) {
			throw new BaseError<InterfaceErrors>('INVALID_SECRET_KEY')
		}
		return {}
	}

	/** Constant-time compare — avoids leaking secret length/prefix via response timing. */
	private secretsMatch(provided: string, expected: string): boolean {
		const a = Buffer.from(provided)
		const b = Buffer.from(expected)
		if (a.length !== b.length) return false
		return timingSafeEqual(a, b)
	}
}

import { describe, it, expect, beforeEach, afterEach } from 'bun:test'
import { InternalSecretKeyMiddleware } from './InternalSecretKeyMiddleware'
import type { HttpControllerRequest } from '@bk-dash/core-typescript'

const KNOWN_SECRET = 'super-secret-key-for-testing'

function makeReq(secret?: string): HttpControllerRequest<unknown> {
	return {
		raw: { headers: { get: (k: string) => (k === 'x-internal-secret' ? secret ?? null : null) } },
		ctx: {},
	} as any
}

describe('InternalSecretKeyMiddleware', () => {
	let original: string | undefined

	beforeEach(() => {
		original = process.env.BILLING_INTERNAL_SECRET
		process.env.BILLING_INTERNAL_SECRET = KNOWN_SECRET
	})

	afterEach(() => {
		if (original === undefined) {
			delete process.env.BILLING_INTERNAL_SECRET
		} else {
			process.env.BILLING_INTERNAL_SECRET = original
		}
	})

	it('resolves without throwing when the correct secret is provided', async () => {
		const mw = new InternalSecretKeyMiddleware()
		const req = makeReq(KNOWN_SECRET)
		await expect(mw.execute(req)).resolves.toMatchObject({})
	})

	it('throws INVALID_SECRET_KEY when the header value does not match the env secret', async () => {
		const mw = new InternalSecretKeyMiddleware()
		const req = makeReq('wrong-secret')
		await expect(mw.execute(req)).rejects.toMatchObject({ name: 'INVALID_SECRET_KEY' })
	})

	it('throws INVALID_SECRET_KEY when the x-internal-secret header is absent', async () => {
		const mw = new InternalSecretKeyMiddleware()
		const req = makeReq() // no secret argument → get() returns null
		await expect(mw.execute(req)).rejects.toMatchObject({ name: 'INVALID_SECRET_KEY' })
	})

	it('throws INVALID_SECRET_KEY when BILLING_INTERNAL_SECRET is unset (fail-closed)', async () => {
		delete process.env.BILLING_INTERNAL_SECRET
		const mw = new InternalSecretKeyMiddleware()
		const req = makeReq(KNOWN_SECRET) // header present but env is gone
		await expect(mw.execute(req)).rejects.toMatchObject({ name: 'INVALID_SECRET_KEY' })
	})
})

